CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','member','guest')), affiliation TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS spaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, all_members INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS space_members (space_id TEXT NOT NULL REFERENCES spaces(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(space_id,user_id));
CREATE TABLE IF NOT EXISTS channels (id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id), name TEXT NOT NULL, mail_address TEXT UNIQUE, mail_policy TEXT NOT NULL DEFAULT 'any', mail_allowlist TEXT NOT NULL DEFAULT '[]', archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS dm_conversations (id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dm_members (dm_id TEXT NOT NULL REFERENCES dm_conversations(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(dm_id,user_id));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, channel_id TEXT REFERENCES channels(id), dm_id TEXT REFERENCES dm_conversations(id), thread_root_id TEXT REFERENCES messages(id), author_id TEXT REFERENCES users(id), external_name TEXT, external_email TEXT, body TEXT NOT NULL, intent TEXT, intent_source TEXT CHECK(intent_source IN ('human','inferred')), due_date TEXT, source TEXT NOT NULL DEFAULT 'chat', source_id TEXT, mail_subject TEXT, mail_message_id TEXT, mail_references TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, edited_at TEXT, deleted_at TEXT, broadcast INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX IF NOT EXISTS idx_messages_channel ON messages(channel_id,thread_root_id,id);
CREATE INDEX IF NOT EXISTS idx_messages_dm ON messages(dm_id,thread_root_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_messages_mail_id ON messages(mail_message_id) WHERE mail_message_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS message_addressees (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending', responded_at TEXT, PRIMARY KEY(message_id,user_id));
CREATE INDEX IF NOT EXISTS idx_addressees_user ON message_addressees(user_id,status);
CREATE TABLE IF NOT EXISTS reactions (message_id TEXT NOT NULL REFERENCES messages(id), user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('了解','ありがとう','要調整','考え中')), PRIMARY KEY(message_id,user_id,kind));
CREATE TABLE IF NOT EXISTS read_states (user_id TEXT NOT NULL REFERENCES users(id), channel_id TEXT, dm_id TEXT, thread_root_id TEXT, last_id TEXT NOT NULL, PRIMARY KEY(user_id,channel_id,dm_id,thread_root_id));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, email TEXT NOT NULL, role TEXT NOT NULL, space_id TEXT REFERENCES spaces(id), expires_at INTEGER NOT NULL, accepted_at INTEGER);
CREATE TABLE IF NOT EXISTS login_codes (email TEXT PRIMARY KEY, code_hash TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, requested_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), filename TEXT NOT NULL, bytes INTEGER NOT NULL, media_type TEXT, r2_key TEXT, omitted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS mail_holds (id TEXT PRIMARY KEY, channel_id TEXT REFERENCES channels(id), sender TEXT NOT NULL, subject TEXT, reason TEXT NOT NULL, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, message_id TEXT, channel_id TEXT, dm_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_events_user ON events(user_id,id);
CREATE TABLE IF NOT EXISTS notification_settings (user_id TEXT PRIMARY KEY REFERENCES users(id), email_enabled INTEGER NOT NULL DEFAULT 1, email_delay_minutes INTEGER NOT NULL DEFAULT 15);
CREATE TABLE IF NOT EXISTS channel_notification_settings (user_id TEXT NOT NULL REFERENCES users(id), channel_id TEXT NOT NULL REFERENCES channels(id), mode TEXT NOT NULL DEFAULT 'mentions', PRIMARY KEY(user_id,channel_id));
CREATE TABLE IF NOT EXISTS push_subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS messages_fts USING fts5(body, message_id UNINDEXED, channel_id UNINDEXED);
